<script setup>
import { computed,onBeforeUnmount,onMounted,reactive,ref } from 'vue'
import { api } from './api'
import ConditionEditor from './ConditionEditor.vue'
import QuestionEditor from './QuestionEditor.vue'

defineProps({currentUser:{type:Object,required:true}})
const flows=ref([]),selected=ref(null),graph=ref({nodes:[],edges:[]}),selectedNodeId=ref(null),selectedEdgeId=ref(null),canvas=ref(null),search=ref(''),error=ref(''),success=ref('')
const tags=ref([]),fields=ref([]),agents=ref([])
const wire=reactive({active:false,sourceNodeId:null,sourceHandle:null,x:0,y:0,hoverNodeId:null,hoverHandle:null})
const insertMenu=ref(null)
const draft=reactive({title:'',text:'',capture_field_id:'',reply_type:'text',required:true,min_length:'',max_length:'',min_value:'',max_value:'',date_format:'%Y-%m-%d',pattern:'',validation_error:'',seconds:60,condition_field:'service_window',operator:'open',value:'',custom_field_key:'',compare_value:'',url:'',method:'POST',body:'',button_label:'',button_action:'next',action_value:''})
const definitions={
 trigger:{label:'Start Bot Flow',icon:'🤖',group:null,inputs:[],outputs:[['next','Compose Next Message']]},
 send_message:{label:'Text',icon:'💬',group:'Messages',inputs:[['input','Message']],outputs:[['next','Next']]},image:{label:'Image',icon:'🖼',group:'Messages',inputs:[['input','Message']],outputs:[['next','Next']]},video:{label:'Video',icon:'🎥',group:'Messages',inputs:[['input','Message']],outputs:[['next','Next']]},audio:{label:'Audio',icon:'🎵',group:'Messages',inputs:[['input','Message']],outputs:[['next','Next']]},file:{label:'File',icon:'📎',group:'Messages',inputs:[['input','Message']],outputs:[['next','Next']]},
 question:{label:'Question',icon:'❓',group:'Interactive',inputs:[['input','Reply']],outputs:[['next','Next']]},interactive:{label:'Interactive Message',icon:'🔘',group:'Interactive',inputs:[['input','Reply']],outputs:[['next','Next'],['buttons','Buttons'],['list_messages','List Messages'],['ecommerce','E-commerce']]},button:{label:'Button',icon:'↖',group:'Interactive',inputs:[['input','Reply']],outputs:[['next','Next'],['sequence','Subscribe to Sequence']]},template:{label:'Template Message',icon:'🧩',group:'Interactive',inputs:[['input','Message']],outputs:[['next','Next']]},
 add_tag:{label:'Add tag',icon:'🏷',group:'Contact',inputs:[['input','Action']],outputs:[['next','Next']]},remove_tag:{label:'Remove tag',icon:'✂',group:'Contact',inputs:[['input','Action']],outputs:[['next','Next']]},set_field:{label:'Set custom field',icon:'📝',group:'Contact',inputs:[['input','Action']],outputs:[['next','Next']]},assign_user:{label:'Assign agent',icon:'👤',group:'Contact',inputs:[['input','Action']],outputs:[['next','Next']]},
 condition:{label:'Condition',icon:'⑂',group:'Flow control',inputs:[['input','Reply']],outputs:[['yes','True'],['no','False']]},delay:{label:'Delay',icon:'⏱',group:'Flow control',inputs:[['input','Action']],outputs:[['next','Next']]},set_status:{label:'Conversation status',icon:'✓',group:'Flow control',inputs:[['input','Action']],outputs:[['next','Next']]},http_request:{label:'HTTP request',icon:'🌐',group:'Integrations',inputs:[['input','Action']],outputs:[['next','Next']]}
}
const groupOrder=['Messages','Interactive','Contact','Flow control','Integrations']
const groups=computed(()=>groupOrder.map(label=>({label,items:Object.entries(definitions).filter(([,d])=>d.group===label&&d.label.toLowerCase().includes(search.value.toLowerCase()))})).filter(g=>g.items.length))
const selectedNode=computed(()=>graph.value.nodes.find(n=>n.id===selectedNodeId.value)||null),selectedEdge=computed(()=>graph.value.edges.find(e=>e.id===selectedEdgeId.value)||null)
const def=n=>definitions[n?.node_type]||{label:n?.node_type||'Block',icon:'⚡',inputs:[['input','Input']],outputs:[['next','Next']]},nodeWidth=250
function nodeById(id){return graph.value.nodes.find(n=>n.id===id)}
function portY(n,handle,kind){const p=kind==='out'?def(n).outputs:def(n).inputs,i=Math.max(0,p.findIndex(x=>x[0]===handle));return 82+i*25}
function nodeHeight(n){return Math.max(125,98+Math.max(def(n).inputs.length,def(n).outputs.length)*25)}
function edgePath(e){const s=nodeById(e.source_node_id),t=nodeById(e.target_node_id);if(!s||!t)return'';return curve(s.position_x+nodeWidth,s.position_y+portY(s,e.source_handle,'out'),t.position_x,t.position_y+portY(t,e.target_handle||'input','in'))}
function curve(sx,sy,tx,ty){const dx=Math.max(70,Math.abs(tx-sx)*.45);return `M ${sx} ${sy} C ${sx+dx} ${sy}, ${tx-dx} ${ty}, ${tx} ${ty}`}
const livePath=computed(()=>{if(!wire.active)return'';const s=nodeById(wire.sourceNodeId);if(!s)return'';return curve(s.position_x+nodeWidth,s.position_y+portY(s,wire.sourceHandle,'out'),wire.x,wire.y)})
function operatorLabel(value){return({open:'is open',closed:'is closed',equals:'is',not_equals:'is not',contains:'contains',not_contains:'does not contain',starts_with:'starts with',ends_with:'ends with',empty:'is empty',not_empty:'is not empty'})[value]||value}
function conditionSummary(c){const field=c.field||'service_window',op=c.operator||'open';if(field==='service_window')return `24-hour window ${op==='closed'?'closed':'open'}`;if(field==='assigned_user'){const name=agents.value.find(a=>String(a.id)===String(c.value))?.name||c.value||'unassigned';return `Assigned agent ${operatorLabel(op)} ${name}`.trim()}if(field==='tag')return `Contact tag ${operatorLabel(op)} ${c.value||''}`.trim();if(field==='conversation_status')return `Status ${operatorLabel(op)} ${c.value||''}`.trim();if(field==='custom_field'){const key=c.field_key||c.key||c.value||'';const label=fields.value.find(f=>f.key===key)?.label||key||'Custom field';return `${label} ${operatorLabel(op)} ${c.compare_value??''}`.trim()}return `${field} ${operatorLabel(op)} ${c.value||''}`.trim()}
function replyTypeLabel(type){return({text:'text',email:'email',phone:'phone',date:'date',number:'number',integer:'whole number',decimal:'number',image:'photo',audio:'audio',video:'video',document:'document',sticker:'sticker',media:'media'})[type]||type}
function questionSummary(c){const message=c.text||'Configure question',type=replyTypeLabel(c.reply_type||'text');const field=fields.value.find(f=>String(f.id)===String(c.capture_field_id));return `${message} · expects ${type}${field?` → ${field.label||field.name||field.key}`:''}`}
function summary(n){const c=n.config||{};if(n.node_type==='trigger')return c.trigger_value||c.trigger_type||'Manual';if(n.node_type==='question')return questionSummary(c);if(['send_message','interactive'].includes(n.node_type))return c.text||'Configure message';if(n.node_type==='condition')return conditionSummary(c);if(n.node_type==='delay')return `${c.seconds||60}s`;if(n.node_type==='http_request')return `${c.method||'POST'} ${c.url||'Configure URL'}`;return n.title||def(n).label}
async function loadConditionData(){const results=await Promise.allSettled([api.contactTags(),api.contactFields(),api.agents()]);if(results[0].status==='fulfilled')tags.value=results[0].value;if(results[1].status==='fulfilled')fields.value=results[1].value;if(results[2].status==='fulfilled')agents.value=results[2].value}
async function loadFlows(){try{flows.value=await api.flows();if(!selected.value&&flows.value.length)await selectFlow(flows.value[0])}catch(e){error.value=e.message}}
async function selectFlow(flow){selected.value=await api.flow(flow.id||flow);graph.value=await api.flowGraph(selected.value.id);clearSelection();if(!graph.value.nodes.length)await seedGraph()}
async function seedGraph(){const trigger=await api.addFlowNode(selected.value.id,{node_type:'trigger',title:'Start Bot Flow',config:{trigger_type:selected.value.trigger_type,trigger_value:selected.value.trigger_value},position_x:80,position_y:100});graph.value.nodes.push(trigger);let prev=trigger,y=100;for(const step of selected.value.steps||[]){const n=await api.addFlowNode(selected.value.id,{node_type:step.step_type,title:null,config:step.config||{},position_x:390,position_y:y});graph.value.nodes.push(n);graph.value.edges.push(await api.addFlowEdge(selected.value.id,{source_node_id:prev.id,source_handle:'next',target_node_id:n.id,target_handle:'input'}));prev=n;y+=170}}
async function addNode(type,pos=null){if(!selected.value)return null;const count=graph.value.nodes.length,base=type==='delay'?{seconds:60}:type==='condition'?{field:'service_window',operator:'open',value:''}:type==='question'?{text:'',capture_field_id:null,reply_type:'text',required:true,date_format:'%Y-%m-%d'}:type==='http_request'?{method:'POST',url:'',body:''}:{};const n=await api.addFlowNode(selected.value.id,{node_type:type,title:def({node_type:type}).label,config:base,position_x:pos?.x??370+(count%3)*300,position_y:pos?.y??100+Math.floor(count/3)*190});graph.value.nodes.push(n);selectNode(n);return n}
function selectNode(n){selectedNodeId.value=n.id;selectedEdgeId.value=null;insertMenu.value=null;const c=n.config||{},customKey=c.field_key||c.key||(c.field==='custom_field'?c.value:'')||'';Object.assign(draft,{title:n.title||'',text:c.text||'',capture_field_id:c.capture_field_id||c.save_reply_field_id||'',reply_type:c.reply_type||c.input_type||'text',required:c.required!==false,min_length:c.min_length??'',max_length:c.max_length??'',min_value:c.min_value??'',max_value:c.max_value??'',date_format:c.date_format||'%Y-%m-%d',pattern:c.pattern||'',validation_error:c.validation_error||'',seconds:c.seconds||60,condition_field:c.field||'service_window',operator:c.operator||'open',value:c.field==='custom_field'?'':(c.value||''),custom_field_key:customKey,compare_value:c.compare_value||'',url:c.url||'',method:c.method||'POST',body:c.body||'',button_label:c.label||'',button_action:c.action||'next',action_value:c.action_value||''})}
function optionalNumber(v){return v===''||v===null||v===undefined?null:Number(v)}
async function saveNode(){const n=selectedNode.value;if(!n)return;let c={...(n.config||{})};if(['send_message','interactive','question'].includes(n.node_type))c.text=draft.text;if(n.node_type==='question')c={...c,capture_field_id:draft.capture_field_id?Number(draft.capture_field_id):null,reply_type:draft.reply_type||'text',required:!!draft.required,min_length:optionalNumber(draft.min_length),max_length:optionalNumber(draft.max_length),min_value:optionalNumber(draft.min_value),max_value:optionalNumber(draft.max_value),date_format:draft.date_format||'%Y-%m-%d',pattern:draft.pattern||'',validation_error:draft.validation_error||''};if(n.node_type==='delay')c.seconds=Number(draft.seconds);if(n.node_type==='condition'){if(draft.condition_field==='custom_field')c={...c,field:'custom_field',operator:draft.operator,field_key:draft.custom_field_key,compare_value:draft.compare_value,value:''};else c={...c,field:draft.condition_field,operator:draft.operator,value:draft.value,field_key:null,compare_value:null}}if(n.node_type==='http_request')c={...c,method:draft.method,url:draft.url,body:draft.body};if(n.node_type==='button')c={...c,label:draft.button_label,action:draft.button_action,action_value:draft.action_value};const u=await api.updateFlowNode(selected.value.id,n.id,{title:draft.title||null,config:c});graph.value.nodes[graph.value.nodes.findIndex(x=>x.id===n.id)]=u;success.value='Changes saved';setTimeout(()=>success.value='',1500)}
async function deleteNode(n){if(n.node_type==='trigger'||!confirm('Delete this block and its connections?'))return;await api.deleteFlowNode(selected.value.id,n.id);graph.value.nodes=graph.value.nodes.filter(x=>x.id!==n.id);graph.value.edges=graph.value.edges.filter(e=>e.source_node_id!==n.id&&e.target_node_id!==n.id);clearSelection()}
async function dragEnd(ev,n){if(wire.active)return;const r=canvas.value.getBoundingClientRect();n.position_x=Math.max(20,Math.round(ev.clientX-r.left-30+canvas.value.scrollLeft));n.position_y=Math.max(20,Math.round(ev.clientY-r.top-20+canvas.value.scrollTop));await api.updateFlowNode(selected.value.id,n.id,{position_x:n.position_x,position_y:n.position_y})}
function stagePoint(ev){const r=canvas.value.getBoundingClientRect();return{x:ev.clientX-r.left+canvas.value.scrollLeft,y:ev.clientY-r.top+canvas.value.scrollTop}}
function startWire(ev,n,handle){ev.preventDefault();ev.stopPropagation();const p=stagePoint(ev);Object.assign(wire,{active:true,sourceNodeId:n.id,sourceHandle:handle,x:p.x,y:p.y,hoverNodeId:null,hoverHandle:null});window.addEventListener('pointermove',moveWire);window.addEventListener('pointerup',cancelWire,{once:true})}
function moveWire(ev){if(!wire.active)return;const p=stagePoint(ev);wire.x=p.x;wire.y=p.y}
function hoverInput(n,handle,on){if(!wire.active||n.id===wire.sourceNodeId)return;if(on){wire.hoverNodeId=n.id;wire.hoverHandle=handle}else if(wire.hoverNodeId===n.id&&wire.hoverHandle===handle){wire.hoverNodeId=null;wire.hoverHandle=null}}
async function finishWire(ev,n,handle){if(!wire.active||n.id===wire.sourceNodeId)return;ev.preventDefault();ev.stopPropagation();const src=wire.sourceNodeId,sh=wire.sourceHandle;cancelWire();try{const duplicate=graph.value.edges.some(e=>e.source_node_id===src&&e.source_handle===sh&&e.target_node_id===n.id&&e.target_handle===handle);if(duplicate)return;const edge=await api.addFlowEdge(selected.value.id,{source_node_id:src,source_handle:sh,target_node_id:n.id,target_handle:handle});graph.value.edges.push(edge);selectedEdgeId.value=edge.id}catch(e){error.value=e.message}}
function cancelWire(){wire.active=false;wire.sourceNodeId=null;wire.sourceHandle=null;wire.hoverNodeId=null;wire.hoverHandle=null;window.removeEventListener('pointermove',moveWire)}
function selectEdge(ev,e){ev.stopPropagation();selectedEdgeId.value=e.id;selectedNodeId.value=null;insertMenu.value=null}
async function deleteEdge(e=selectedEdge.value){if(!e)return;await api.deleteFlowEdge(selected.value.id,e.id);graph.value.edges=graph.value.edges.filter(x=>x.id!==e.id);selectedEdgeId.value=null;insertMenu.value=null}
function openInsert(e){const s=nodeById(e.source_node_id),t=nodeById(e.target_node_id);insertMenu.value={edge:e,x:(s.position_x+t.position_x)/2+nodeWidth/2,y:(s.position_y+t.position_y)/2}}
async function insertBlock(type){const m=insertMenu.value;if(!m)return;const old=m.edge;try{const n=await addNode(type,{x:m.x-nodeWidth/2,y:m.y-60});await api.deleteFlowEdge(selected.value.id,old.id);graph.value.edges=graph.value.edges.filter(e=>e.id!==old.id);const e1=await api.addFlowEdge(selected.value.id,{source_node_id:old.source_node_id,source_handle:old.source_handle,target_node_id:n.id,target_handle:def(n).inputs[0]?.[0]||'input'});const e2=await api.addFlowEdge(selected.value.id,{source_node_id:n.id,source_handle:def(n).outputs[0]?.[0]||'next',target_node_id:old.target_node_id,target_handle:old.target_handle||'input'});graph.value.edges.push(e1,e2);insertMenu.value=null;selectedEdgeId.value=null}catch(e){error.value=e.message}}
function clearSelection(){selectedNodeId.value=null;selectedEdgeId.value=null;insertMenu.value=null;cancelWire()}
function keydown(e){if((e.key==='Delete'||e.key==='Backspace')&&selectedEdge.value&&!['INPUT','TEXTAREA','SELECT'].includes(document.activeElement?.tagName)){e.preventDefault();deleteEdge()}if(e.key==='Escape')clearSelection()}
onMounted(()=>{loadFlows();loadConditionData();window.addEventListener('keydown',keydown)});onBeforeUnmount(()=>{window.removeEventListener('keydown',keydown);cancelWire()})
</script>

<template><section class="vfb"><aside class="palette"><div class="palette-head"><b>Flow blocks</b><small>Drag wiring from an output dot to an input dot</small></div><input v-model="search" placeholder="Search blocks…"><section v-for="g in groups" :key="g.label"><h4>{{g.label}}</h4><button v-for="[type,d] in g.items" :key="type" @click="addNode(type)"><span>{{d.icon}}</span>{{d.label}}</button></section></aside>
<main class="main"><header class="toolbar"><select v-if="flows.length" :value="selected?.id||''" @change="selectFlow(Number($event.target.value))"><option v-for="f in flows" :key="f.id" :value="f.id">{{f.name}}</option></select><div class="legend"><span>Drag ● output → ● input</span><span>Click a line to edit it</span></div></header>
<div v-if="selected" ref="canvas" class="stage" @click.self="clearSelection"><svg class="edges"><path v-for="e in graph.edges" :key="e.id" :d="edgePath(e)" :class="{selected:selectedEdgeId===e.id}" @click="selectEdge($event,e)" @dblclick.stop="deleteEdge(e)"/><path v-if="wire.active" :d="livePath" class="live"/></svg>
<article v-for="n in graph.nodes" :key="n.id" class="node" :class="[n.node_type,{selected:selectedNodeId===n.id}]" :style="{left:n.position_x+'px',top:n.position_y+'px',minHeight:nodeHeight(n)+'px'}" draggable="true" @dragend="dragEnd($event,n)" @click.stop="selectNode(n)"><header><span>{{def(n).icon}}</span><strong>{{n.title||def(n).label}}</strong><button v-if="n.node_type!=='trigger'" @click.stop="deleteNode(n)">×</button></header><p>{{summary(n)}}</p><div v-for="([handle,label],i) in def(n).inputs" :key="'i'+handle" class="port input" :style="{top:(70+i*25)+'px'}"><button :class="{valid:wire.active&&wire.sourceNodeId!==n.id,hover:wire.hoverNodeId===n.id&&wire.hoverHandle===handle}" @pointerenter="hoverInput(n,handle,true)" @pointerleave="hoverInput(n,handle,false)" @pointerup="finishWire($event,n,handle)"></button><span>{{label}}</span></div><div v-for="([handle,label],i) in def(n).outputs" :key="'o'+handle" class="port output" :style="{top:(70+i*25)+'px'}"><span>{{label}}</span><button :class="{wiring:wire.active&&wire.sourceNodeId===n.id&&wire.sourceHandle===handle}" @pointerdown="startWire($event,n,handle)"></button></div></article>
<div v-if="wire.active" class="hint">Drag to a highlighted input port · Esc to cancel</div><div v-if="selectedEdge" class="edge-tools"><b>Connection</b><button @click="openInsert(selectedEdge)">＋ Insert block</button><button class="danger" @click="deleteEdge()">× Remove</button></div><div v-if="insertMenu" class="insert-menu" :style="{left:insertMenu.x+'px',top:insertMenu.y+'px'}"><b>Insert block</b><button v-for="[type,d] in Object.entries(definitions).filter(([,d])=>d.group)" :key="type" @click="insertBlock(type)"><span>{{d.icon}}</span>{{d.label}}</button></div></div></main>
<aside v-if="selectedNode" class="drawer"><div class="drawer-head"><span>{{def(selectedNode).icon}}</span><div><h2>{{def(selectedNode).label}}</h2><p>Configure this block</p></div></div><div class="drawer-body"><label>Title<input v-model="draft.title"></label><label v-if="['send_message','interactive','question'].includes(selectedNode.node_type)">Message<textarea v-model="draft.text" rows="6"></textarea></label><QuestionEditor v-if="selectedNode.node_type==='question'" :draft="draft" :fields="fields"/><label v-if="selectedNode.node_type==='delay'">Delay seconds<input v-model.number="draft.seconds" type="number" min="1"></label><ConditionEditor v-if="selectedNode.node_type==='condition'" :draft="draft" :tags="tags" :fields="fields" :agents="agents"/><template v-if="selectedNode.node_type==='http_request'"><label>Method<select v-model="draft.method"><option>GET</option><option>POST</option><option>PUT</option><option>PATCH</option><option>DELETE</option></select></label><label>URL<input v-model="draft.url"></label><label>Body<textarea v-model="draft.body" rows="6"></textarea></label></template><template v-if="selectedNode.node_type==='button'"><label>Button label<input v-model="draft.button_label"></label><label>Action<select v-model="draft.button_action"><option value="next">Continue</option><option value="start_flow">Start flow</option><option value="send_message">Send message</option><option value="url">Open URL</option></select></label><label v-if="draft.button_action!=='next'">Action value<input v-model="draft.action_value"></label></template></div><footer><button @click="selectedNodeId=null">Close</button><button class="save" @click="saveNode">Save changes</button></footer></aside><p v-if="error" class="toast error">{{error}}</p><p v-if="success" class="toast">{{success}}</p></section></template>

<style scoped>
